import json, subprocess
from pathlib import Path
root=Path('blueprints/runtime-workers/deerflow')
files=[p for p in root.rglob('*') if p.is_file() and '.research' not in p.parts and '__pycache__' not in p.parts]
counts={'python':0,'shell':0,'json':0}
for path in [*files, Path('tests/test_runtime_worker_deerflow.py')]:
    if path.suffix == '.py':
        compile(path.read_text(), str(path), 'exec'); counts['python']+=1
    elif path.suffix == '.sh':
        shell='bash' if path.parent==root else 'sh'
        subprocess.run([shell,'-n',str(path)],check=True); counts['shell']+=1
    elif path.suffix in ('.json','.template','.example'):
        json.loads(path.read_text()); counts['json']+=1
    if path.suffix != '.pyc':
        assert all(line.rstrip()==line for line in path.read_text().splitlines()), path.name
print(json.dumps({'status':'passed','syntax_files':counts,'whitespace':'checked all delivered files, including untracked files'}))
